    customerId,
    limit,
    ...(status === null ? {} : { status: status as OrderStatus }),
    ...(cursor === null ? {} : { after: decodeCursor(cursor) }),
  };
}
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { InvalidStateError, ValidationError } from "../src/core/errors.js";
import { canCancel, cancel, createOrder, totalCents, type NewOrder } from "../src/core/order.js";

const META = { id: "ord-1", placedAt: "2026-10-10T12:00:00.000Z" };

function newOrder(overrides: Partial<NewOrder> = {}): NewOrder {
  return {
    customerId: "cust-1",
    customerEmail: "jane@example.com",
    channel: "web",
    currency: "USD",
    lines: [{ sku: "SKU-1", name: "Desk lamp", qty: 2, unitPriceCents: 625 }],
    ...overrides,
  };
}

function issuePaths(fn: () => unknown): string[] {
  try {
    fn();
  } catch (error) {
    assert.ok(error instanceof ValidationError);
    return error.issues.map((issue) => issue.path);
  }
  assert.fail("expected a ValidationError");
}

describe("createOrder", () => {
  it("builds a placed order and computes the total in cents", () => {
    const order = createOrder(
      newOrder({
        lines: [
          { sku: "A", name: "Cable", qty: 3, unitPriceCents: 499 },
          { sku: "B", name: "Adapter", qty: 1, unitPriceCents: 1000 },
        ],
      }),
      META,
    );
    assert.equal(order.status, "placed");
    assert.equal(order.placedAt, META.placedAt);
    assert.equal(totalCents(order), 2497);
  });

  it("requires at least one line", () => {
    assert.deepEqual(issuePaths(() => createOrder(newOrder({ lines: [] }), META)), ["lines"]);
  });

  it("rejects non-positive and fractional quantities and non-integer prices", () => {
    const bad = newOrder({
      lines: [
        { sku: "A", name: "x", qty: 0, unitPriceCents: 100 },
        { sku: "B", name: "x", qty: 1.5, unitPriceCents: 100 },
        { sku: "C", name: "x", qty: 1, unitPriceCents: 9.99 },
      ],
    });
    assert.deepEqual(issuePaths(() => createOrder(bad, META)), [
      "lines[0].qty",
      "lines[1].qty",
      "lines[2].unitPriceCents",
    ]);
  });

  it("reports every problem at once", () => {
    const paths = issuePaths(() =>
      createOrder(newOrder({ customerId: " ", customerEmail: "nope", currency: "ZZZ", channel: "fax" as never }), META),
    );
    assert.deepEqual(paths, ["customerId", "customerEmail", "channel", "currency"]);
  });

  it("bounds the order total", () => {
    const huge = newOrder({ lines: [{ sku: "A", name: "x", qty: 1000, unitPriceCents: 999_999 }] });
    assert.deepEqual(issuePaths(() => createOrder(huge, META)), ["lines"]);
  });
});

describe("cancel", () => {
  it("moves a placed order to cancelled once", () => {
    const placed = createOrder(newOrder(), META);
    const cancelled = cancel(placed, "2026-10-11T08:00:00.000Z");
    assert.equal(cancelled.status, "cancelled");
    assert.equal(cancelled.cancelledAt, "2026-10-11T08:00:00.000Z");
    assert.equal(placed.status, "placed");
    assert.throws(() => cancel(cancelled, "2026-10-12T08:00:00.000Z"), InvalidStateError);
  });

  it("refuses to cancel after the cancellation window", () => {
    const placed = createOrder(newOrder(), META);
    assert.equal(canCancel(placed, "2026-11-09T12:00:00.000Z"), true);
    assert.throws(() => cancel(placed, "2026-11-10T12:00:01.000Z"), /cancellation window/);
  });
});
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { OrderCancelled, OrderPlaced } from "../src/core/events.js";
import { FIXED_NOW, FakePayments, makeApp, placeOrderBody } from "./helpers.js";

describe("POST /orders", () => {
  it("places an order, answers 201 and publishes OrderPlaced v3", async () => {
    const { app, publisher, payments } = makeApp();
    const res = await app.handle("POST", "/orders", placeOrderBody());

    assert.equal(res.status, 201);
    assert.deepEqual(res.body, {
      id: "ord-1",
      status: "placed",
      placedAt: FIXED_NOW,
      currency: "USD",
      totalCents: 1250,
      lines: [{ sku: "SKU-1", name: "Desk lamp", qty: 2, unitPriceCents: 625 }],
    });
    assert.equal(publisher.events.length, 1);
    assert.deepEqual(publisher.events[0], {
      type: "OrderPlaced",
      schemaVersion: 3,
      orderId: "ord-1",
      customerId: "cust-1",
      customerEmail: "jane@example.com",
      placedAt: FIXED_NOW,
      channel: "web",
      currency: "USD",
      totalCents: 1250,
      lines: [{ sku: "SKU-1", qty: 2, unitPriceCents: 625 }],
    } satisfies OrderPlaced);
    assert.deepEqual(payments.requests, [
      { orderId: "ord-1", customerId: "cust-1", amountMinor: 1250, currency: "USD" },
    ]);
  });

  it("handles a multi-line order with a total of 2497 cents", async () => {
    const { app, publisher } = makeApp();
    const res = await app.handle(
      "POST",
      "/orders",
      placeOrderBody({
        lines: [
          { sku: "CAB-1", name: "Cable", qty: 3, unitPriceCents: 499 },
          { sku: "ADP-1", name: "Adapter", qty: 1, unitPriceCents: 1000 },
        ],
      }),
    );
    assert.equal(res.status, 201);
    assert.equal((publisher.events[0] as OrderPlaced).totalCents, 2497);
  });

  it("answers 400 with every issue for an invalid body and publishes nothing", async () => {
    const { app, publisher, payments } = makeApp();
    const res = await app.handle(
      "POST",
      "/orders",
      placeOrderBody({ currency: "ZZZ", lines: [{ sku: "SKU-1", name: "x", qty: 0, unitPriceCents: 100 }] }),
    );
    assert.equal(res.status, 400);
    const error = (res.body as { error: { code: string; details: Array<{ path: string }> } }).error;
    assert.equal(error.code, "validation_failed");
    assert.deepEqual(error.details.map((d) => d.path), ["currency", "lines[0].qty"]);
    assert.equal(publisher.events.length, 0);
    assert.equal(payments.requests.length, 0);
  });

  it("answers 400 for wrong types and a missing body", async () => {
    const { app } = makeApp();
    const wrongType = await app.handle("POST", "/orders", placeOrderBody({ customerId: 42, lines: "none" }));
    assert.equal(wrongType.status, 400);
    const missing = await app.handle("POST", "/orders", undefined);
    assert.equal(missing.status, 400);
  });

  it("answers 402 when the payment is declined and keeps nothing", async () => {
    const { app, publisher } = makeApp(new FakePayments({ authorized: false, declineReason: "card_expired" }));
